      ctx.ui.setStatus("smoke-b", "SECOND STATUS");
    },
  });
  pi.registerCommand("smoke-clear", {
    description: "Remove smoke-test statuses",
    handler: async (_args, ctx) => {
      ctx.ui.setStatus("smoke-a", undefined);
      ctx.ui.setStatus("smoke-b", undefined);
    },
  });
