    },
  });
  pi.registerCommand("smoke-prompt", {
    description: "Open a real extension confirmation prompt",
    handler: async (_args, ctx) => {
      await ctx.ui.confirm("SMOKE CONFIRM", "Inspect waiting activity, then dismiss.");
